def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    parent = list(range(h * w))
    rank = [0] * (h * w)
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        x, y = find(x), find(y)
        if x == y: return False
        if rank[x] < rank[y]: x, y = y, x
        parent[y] = x
        if rank[x] == rank[y]: rank[x] += 1
        return True
    def idx(r, c): return r * w + c
    # Existing foreground adjacency forms the initial components.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg: continue
            if r and grid[r-1][c] != bg: union(idx(r,c), idx(r-1,c))
            if c and grid[r][c-1] != bg: union(idx(r,c), idx(r,c-1))
    # Possible straight bridges between successive original marks in each row/column.
    bridges = []
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] != bg]
        for a, b in zip(cs, cs[1:]):
            if b > a + 1: bridges.append((b-a-1, 0, r, a, b))
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(rs, rs[1:]):
            if b > a + 1: bridges.append((b-a-1, 1, c, a, b))
    # Prefer short links; each painted bridge joins two previously separate components.
    bridges.sort()
    for gap, orient, fixed, a, b in bridges:
        p1 = idx(fixed, a) if orient == 0 else idx(a, fixed)
        p2 = idx(fixed, b) if orient == 0 else idx(b, fixed)
        if find(p1) == find(p2): continue
        for t in range(a + 1, b):
            r, c = (fixed, t) if orient == 0 else (t, fixed)
            out[r][c] = 2
            union(idx(r,c), p1)
        union(p1, p2)
    return out
